const icons={overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',washer:'<rect x="4" y="2" width="16" height="20" rx="2"/><circle cx="12" cy="14" r="5"/><path d="M4 7h16M7 4.5h2m7 0h1M8 14c3-3 5 3 8 0"/>',micro:'<rect x="2" y="5" width="20" height="14" rx="2"/><rect x="5" y="8" width="11" height="8" rx="1"/><path d="M19 9v1m0 3v2M5 21v-2m14 2v-2"/>',fridge:'<rect x="5" y="2" width="14" height="20" rx="2"/><path d="M5 9h14M9 5v1m0 7v4M12 2v20"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6m10-6v6M3 11h18m-13 5h2m4 0h2"/>',basket:'<path d="M3 9h18l-2 12H5L3 9Zm3 0 4-7m8 7-4-7M8 12v6m4-6v6m4-6v6M2 9h20"/>',shield:'<path d="m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6l9-4Z"/><path d="m8 12 3 3 5-6"/>',activity:'<path d="M2 12h5l3-8 4 16 3-8h5"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>'};const svg=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.overview}</svg>`;
const seed=()=>({micro:'Available',washer:'In Use',washEnd:Date.now()+18*60000,bookings:[],baskets:[{id:'A1',user:'Alex Johnson',weight:1.85,locked:true,pin:'1234'},{id:'A2',user:'Sam Rivera',weight:2.4,locked:true,pin:'2468'},{id:'A3',user:null,weight:0,locked:true,pin:'1234'},{id:'B1',user:'Maya Chen',weight:1.2,locked:true,pin:'2468'},{id:'B2',user:null,weight:0,locked:true,pin:'1234'},{id:'B3',user:'Jordan Lee',weight:3.1,locked:true,pin:'2468'}],events:[{title:'Basket A1 secured',detail:'Alex Johnson · Authorized PIN access',time:Date.now()-12*60000},{title:'Washing cycle started',detail:'Sam Rivera · Washing machine 01',time:Date.now()-27*60000},{title:'Microwave is available',detail:'Cycle finished · Ready for the next meal',time:Date.now()-40*60000}],alerts:[],notifications:[],fridge:'Available',failedPins:0});let state;try{state=JSON.parse(localStorage.getItem('smartdorm-v1'))||seed()}catch{state=seed()}let page='overview',timer,activeBasket=null;const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function save(){localStorage.setItem('smartdorm-v1',JSON.stringify(state))}function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}function event(title,detail){state.events.unshift({title,detail,time:Date.now()});state.events=state.events.slice(0,50);save()}function notify(title,detail){state.notifications.unshift({title,detail,time:Date.now()});save();toast(title)}const ago=t=>{let m=Math.floor((Date.now()-t)/60000);return m<1?'Just now':m<60?m+' min ago':Math.floor(m/60)+' hr ago'};const remaining=()=>Math.max(0,Math.ceil((state.washEnd-Date.now())/60000));const pill=(s,t)=>`<span class="pill ${t||(/Use|collection|Occupied/.test(s)?'amber':/Offline/.test(s)?'gray':'')}"><i></i>${s}</span>`;function heading(k,title,desc,action=''){return `<div class="page-heading"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p>${desc}</p></div>${action||`<div class="date">${svg('calendar').replace('<svg','<svg style="width:16px;height:16px"')} ${new Date().toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short',year:'numeric'})}</div>`}</div>`}function nav(){let links=[['overview','overview','Overview'],['appliances','washer','Appliances'],['bookings','calendar','My bookings'],['baskets','basket','My baskets'],['activity','activity','Activity'],['admin','shield','Admin demo']];$('#nav').innerHTML=links.map(([id,ic,label])=>`<a href="#${id}" class="${page===id?'active':''}">${svg(ic)}<span class="nav-text">${label}</span>${id==='bookings'&&state.bookings.length?`<span class="nav-count">${state.bookings.length}</span>`:''}</a>`).join('');$('#crumb').textContent=links.find(x=>x[0]===page)?.[2]||'Overview';$('#notif-count').style.display=state.notifications.length?'block':'none'}function devices(){let occupied=state.baskets.filter(b=>b.user).length;return `<div class="cards"><article class="card"><div class="card-top"><div class="device-icon">${svg('micro')}</div>${pill(state.micro)}</div><h3>Smart microwave</h3><span class="sub">Kitchen area · Microwave 01</span><div class="device-detail"><strong>${state.micro==='Available'?'Ready when you are':state.micro==='In Use'?'Something’s cooking':'Temporarily offline'}</strong><p>${state.micro==='Available'?'Your next warm meal is a moment away.':state.micro==='In Use'?'A student is using the microwave.':'Ask your residence administrator for help.'}</p></div><button class="btn" data-action="micro">View microwave <span>↗</span></button></article><article class="card"><div class="card-top"><div class="device-icon">${svg('washer')}</div>${pill(state.washer)}</div><h3>Smart washing machine</h3><span class="sub">Laundry room · Washing machine 01</span><div class="device-detail"><div class="row"><strong>${state.washer==='In Use'?`<span id="wash-min">${remaining()}</span> min remaining`:state.washer==='Awaiting collection'?'Ready for collection':state.washer==='Offline'?'Temporarily offline':'A fresh start awaits'}</strong></div><p>${state.washer==='In Use'?'Washing in progress · Sam Rivera':state.washer==='Awaiting collection'?'Cycle complete · Clothes still inside':'Book a slot and skip the guesswork.'}</p><div class="progress"><i style="width:${state.washer==='In Use'?Math.max(5,100-remaining()/45*100):state.washer==='Awaiting collection'?100:0}%"></i></div></div><button class="btn primary" data-action="book">Book a time slot <span>↗</span></button></article><article class="card"><div class="card-top"><div class="device-icon">${svg('fridge')}</div>${pill(state.fridge==='Offline'?'Offline':'Connected')}</div><h3>Smart refrigerator</h3><span class="sub">Kitchen area · Refrigerator 01</span><div class="device-detail"><strong>${occupied}<span style="color:#a2afb1;font-size:13px"> / 6 baskets occupied</span></strong><p>Your basket A1 is ${state.baskets[0].locked?'locked and secure.':'currently unlocked.'}</p><div class="progress"><i style="width:${occupied/6*100}%"></i></div></div><button class="btn" data-go="baskets">Access my basket <span>↗</span></button></article></div>`}function activities(limit=3){return state.events.slice(0,limit).map(e=>`<div class="activity-row"><span class="activity-symbol">✓</span><div>${esc(e.title)}<p>${esc(e.detail)}</p></div><time>${ago(e.time)}</time></div>`).join('')}function bookingCard(b){let d=new Date(b.start);return `<div class="booking-preview"><div class="calendar-block">${d.toLocaleString('en',{month:'short'}).toUpperCase()}<b>${d.getDate()}</b></div><div><h4>Washing machine 01</h4><p>${d.toLocaleDateString('en',{weekday:'short'})} · ${d.toLocaleTimeString('en',{hour:'2-digit',minute:'2-digit'})} – ${new Date(b.end).toLocaleTimeString('en',{hour:'2-digit',minute:'2-digit'})}</p></div>${pill('Confirmed')}</div>`}function overview(){return heading('Your connected campus','Good evening, Alex <span style="font-size:24px">✦</span>','A little less waiting. A little more living.')+`<section class="hero"><div class="hero-copy"><div class="eyebrow">A SMARTER WAY TO SHARE</div><h2>Your everyday, connected.</h2><p>Check what’s free, plan your laundry, and keep your food secure. All from right here.</p></div><div class="hero-art" aria-hidden="true"><div class="appliance micro"></div><div class="appliance washer"></div><div class="appliance fridge"></div></div></section><div class="section-head"><h2>Your shared appliances</h2><span class="live"><i></i>Live demo updates</span></div>${devices()}<div class="bottom-grid"><section class="panel"><div class="panel-head"><h2>My next booking</h2><button class="text-button" data-go="bookings">View all ↗</button></div>${state.bookings.length?bookingCard([...state.bookings].sort((a,b)=>a.start-b.start)[0]):`<div class="booking-preview"><div class="calendar-block">${svg('calendar')}</div><div><h4>A little planning goes a long way.</h4><p>No upcoming bookings. Find your perfect laundry slot.</p></div><button class="text-button" data-action="book">Book ↗</button></div>`}<div class="tip">◷ &nbsp; A reserved slot means less time waiting in line.</div></section><section class="panel"><div class="panel-head"><h2>Recent activity</h2><button class="text-button" data-go="activity">View all ↗</button></div>${activities()}</section></div><div class="note">◈ &nbsp; <b>A shared space, a little smarter.</b> You’re exploring a live simulation. All users, sensors, and appliance activity are demo data.</div>`}function basketPage(){let n=state.baskets.filter(b=>b.user).length;return heading('KEEP IT COOL','Your food. Your space.','The fridge doors open normally. Individual baskets keep your items separate.')+`<div class="stats"><div class="stat"><small>REFRIGERATOR</small><strong>4.2°<span style="font-size:14px">C</span></strong><small>Simulated temperature</small></div><div class="stat"><small>OCCUPIED BASKETS</small><strong>${n} / 6</strong><small>Individual PIN locks</small></div><div class="stat"><small>AVAILABLE BASKETS</small><strong>${6-n}</strong><small>Admin can assign a basket</small></div></div><div class="section-head"><h2>Inside your refrigerator</h2>${pill(state.fridge==='Offline'?'Offline':'Connected')}</div><div class="basket-grid">${state.baskets.map(b=>`<article class="basket ${b.user==='Alex Johnson'?'mine':''}"><div class="row"><h3>Basket ${b.id}</h3>${b.user==='Alex Johnson'?'<span class="badge">YOURS</span>':pill(b.user?'Occupied':'Available',b.user?'gray':'')}</div><div class="basket-visual">${svg('basket')}</div><p>${b.user?esc(b.user):'Not assigned'}<br>${b.user?`${b.locked?'Locked':'Unlocked'} · ${b.weight.toFixed(2)} kg`:'Ready for a new resident'}</p><button class="btn ${b.user==='Alex Johnson'?'primary':''}" data-basket="${b.id}">${b.user==='Alex Johnson'?'Access basket':b.user?'View basket':'View availability'} ↗</button></article>`).join('')}</div><div class="note"><b>Sensor readings need context.</b> Weight changes can result from normal use, sensor drift, or a misplaced item. An alert requests a review and never proves theft.</div>`}function bookingsPage(){return heading('MAKE TIME FOR YOU','My bookings','Your laundry plans, without the waiting.',`<button class="btn primary" data-action="book">+ New booking</button>`)+`<div class="panel"><div class="panel-head"><h2>Upcoming reservations</h2><span class="live">${state.bookings.length} booking${state.bookings.length===1?'':'s'}</span></div>${state.bookings.length?state.bookings.map(b=>`<div class="list-item">${bookingCard(b)}<div class="actions"><button class="btn" data-start="${b.id}">Start cycle</button><button class="btn danger" data-cancel="${b.id}">Cancel</button></div></div>`).join(''):'<div class="empty">Your next laundry day starts here.<br><br><button class="btn primary" data-action="book">Find a time slot ↗</button></div>'}</div><div class="note"><b>One machine. No double bookings.</b> Reservations cannot overlap. Each slot lasts 45 minutes. A finished wash stays “Awaiting collection” until clothes are collected.</div>`}function adminPage(){return heading('RESIDENCE CONTROL','Admin dashboard','Manage the demo floor and bring IoT scenarios to life.')+`<div class="note" style="margin:0 0 22px"><b>Demo admin access</b> · Mock identities only. Changes are saved in this browser. No real devices are connected.</div><div class="admin-grid"><section class="panel"><h2>Appliance controls</h2>${[['micro','Microwave',['Available','In Use','Offline']],['washer','Washing machine',['Available','In Use','Awaiting collection','Offline']],['fridge','Refrigerator',['Available','Offline']]].map(([k,n,opts])=>`<label class="field">${n}<select data-device="${k}">${opts.map(s=>`<option ${state[k]===s?'selected':''}>${s}</option>`).join('')}</select></label>`).join('')}<div class="row"><button class="btn primary" data-action="complete">Complete wash cycle</button><button class="btn" data-action="collect">Collect clothes</button></div><button class="btn" data-action="unexpected">Simulate unusual weight change</button></section><section class="panel"><h2>Basket assignments</h2><p style="font-size:11px">Assignment changes reset the basket lock. Alex’s demo PIN is 1234; other assigned baskets use 2468.</p>${state.baskets.map(b=>`<label class="field">Basket ${b.id}<select data-assign="${b.id}">${['','Alex Johnson','Sam Rivera','Maya Chen','Jordan Lee'].map(u=>`<option value="${u}" ${b.user===u||(!b.user&&!u)?'selected':''}>${u||'Available / unassigned'}</option>`).join('')}</select></label>`).join('')}</section><section class="panel"><div class="panel-head"><h2>Alerts for review</h2><span class="badge">${state.alerts.filter(a=>!a.resolved).length} open</span></div>${state.alerts.length?state.alerts.map(a=>`<div class="notification"><b>${esc(a.title)}</b><p>${esc(a.detail)}</p><small>${ago(a.time)} · ${a.resolved?'Reviewed':'Needs review'}</small>${!a.resolved?`<br><button class="text-button" data-resolve="${a.id}">Mark reviewed ✓</button>`:''}</div>`).join(''):'<div class="empty">No alerts. Your floor is looking good.</div>'}</section><section class="panel"><h2>All reservations</h2>${state.bookings.length?state.bookings.map(b=>`<div class="list-item"><div><h3>${esc(b.user)} · Washing machine 01</h3><p>${new Date(b.start).toLocaleString()}</p></div><button class="text-button" data-cancel="${b.id}">Cancel</button></div>`).join(''):'<div class="empty">No reservations to manage yet.</div>'}<button class="btn danger" data-action="reset">Reset demo</button></section></div>`}function render(){nav();$('#main').innerHTML=page==='overview'?overview():page==='appliances'?heading('FLOOR 02 · CONNECTED','Shared appliances','Real-time demo status, wherever you are.')+devices()+`<div class="note">Simulated IoT adapter · Status readings update immediately across the app. Use Admin demo to trigger sensor scenarios.</div>`:page==='bookings'?bookingsPage():page==='baskets'?basketPage():page==='admin'?adminPage():heading('THE PULSE OF YOUR FLOOR','Activity feed','A clear history of appliance and basket activity.')+`<section class="panel">${activities(50)}</section>`}function modal(html){$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true"><button class="close" aria-label="Close dialog" data-action="close">×</button>${html}</section></div>`;setTimeout(()=>$('.modal input, .modal button:not(.close)')?.focus(),50)}function close(){$('#modal-root').innerHTML='';activeBasket=null}function book(){let d=new Date(Date.now()+3600000);d.setMinutes(0,0,0);let val=new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16);modal(`<div class="eyebrow">LAUNDRY, ON YOUR TERMS</div><h2 style="margin-top:12px">Reserve your next fresh start.</h2><p>Washing machine 01 · Maple Hall, Floor 02<br>45 minute cycle · Alex Johnson (demo)</p><form id="book-form"><label class="field">Start date & time<input required id="booking-time" type="datetime-local" value="${val}"></label><div class="note" style="margin:10px 0">Your slot is reserved for 45 minutes. Please collect your clothes after the cycle finishes.</div><div class="error" id="book-error" role="alert"></div><button class="btn primary" type="submit" style="width:100%">Confirm reservation ↗</button></form>`)}function access(id){let b=state.baskets.find(b=>b.id===id);activeBasket=id;if(!b.user){modal(`<h2>Basket ${id}</h2><p>This basket is available. Ask the administrator to assign it from the Admin demo dashboard.</p><button class="btn primary" data-go="admin">Open Admin demo</button>`);return}if(b.user!=='Alex Johnson'){modal(`<h2>Basket ${id}</h2><p>This basket is assigned to ${esc(b.user)}. You can only unlock baskets assigned to Alex Johnson, the current demo student.</p>${pill(b.locked?'Locked':'Unlocked')}<p>No personal information is collected in this demo.</p>`);return}if(state.fridge==='Offline'){toast('Refrigerator controller is offline. Restore it in Admin demo.');return}if(!b.locked){unlocked(b);return}modal(`<div class="eyebrow">YOUR PERSONAL STORAGE</div><h2 style="margin-top:12px">Unlock basket ${id}</h2><p>The main refrigerator opens normally. Enter your assigned basket PIN to release its individual lock.</p><form id="pin-form"><label class="field">4-digit basket PIN<input id="pin" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" type="password" required autocomplete="off" placeholder="••••"></label><p>Demo PIN: <b>1234</b> · Mock user: Alex Johnson</p><div class="error" id="pin-error" role="alert"></div><button class="btn primary" style="width:100%" type="submit">Unlock basket ↗</button></form>`)}function unlocked(b){activeBasket=b.id;modal(`<div class="eyebrow">BASKET ${b.id} · UNLOCKED</div><h2 style="margin-top:12px">Make yourself at home.</h2><p>Your basket lock is open. Simulate adding or removing an item to see the weight sensor update.</p><div class="sensor"><small>SIMULATED WEIGHT SENSOR</small><strong>${b.weight.toFixed(2)} <span style="font-size:15px">kg</span></strong><small>Live reading · Basket ${b.id}</small></div><div class="weight-actions"><button class="btn" data-weight="0.25">+ Add 250 g</button><button class="btn" data-weight="-0.25">− Remove 250 g</button></div><button class="btn primary" data-lock="${b.id}" style="width:100%">Lock basket & finish ✓</button><p style="font-size:10px">Weight changes are observations, never conclusive proof of theft.</p>`);activeBasket=b.id}function alertEvent(title,detail){state.alerts.unshift({id:crypto.randomUUID(),title,detail,time:Date.now(),resolved:false});event(title,detail);notify('Activity flagged for review',detail)}function complete(){if(state.washer!=='In Use'){toast('Start a wash cycle first.');return}state.washer='Awaiting collection';event('Washing cycle completed','Clothes remain in the machine · Awaiting collection');notify('Your wash is complete','Please collect your clothes. The machine is not available until collection.');save();render()}function collect(){if(state.washer!=='Awaiting collection'){toast('Collection is available after a wash cycle completes.');return}state.washer='Available';event('Clothes collected','Washing machine 01 is now available');save();render();toast('Clothes collected. The machine is available.')}function microModal(){modal(`<div class="eyebrow">KITCHEN · MICROWAVE 01</div><h2 style="margin-top:12px">A warm meal awaits.</h2>${pill(state.micro)}<p>This status is visible remotely. This demonstration uses a simulated appliance controller.</p><button class="btn primary" data-action="micro-toggle">${state.micro==='In Use'?'Finish heating':state.micro==='Offline'?'Reconnect demo appliance':'Start demo heating'}</button><p style="font-size:10px">A demo heating cycle automatically finishes after 20 seconds.</p>`)}
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='book-form'){let start=new Date($('#booking-time').value).getTime(),end=start+45*60000;if(!Number.isFinite(start)||start<Date.now()){$('#book-error').textContent='Choose a start time in the future.';return}if(state.washer==='Offline'){$('#book-error').textContent='The machine is offline. Ask the demo admin to reconnect it.';return}if(state.bookings.some(b=>start<b.end&&end>b.start)||(state.washer==='In Use'&&start<state.washEnd)){$('#book-error').textContent='That time overlaps another reservation or the current cycle. Please choose another slot.';return}state.bookings.push({id:crypto.randomUUID(),user:'Alex Johnson',start,end});event('Laundry slot reserved',new Date(start).toLocaleString()+' · Alex Johnson');save();close();render();toast('Your laundry slot is confirmed.')}if(e.target.id==='pin-form'){let b=state.baskets.find(b=>b.id===activeBasket);if($('#pin').value!==b.pin){state.failedPins++;event('Unsuccessful PIN attempt',`Basket ${b.id} · Access denied`);if(state.failedPins%3===0)alertEvent('Repeated unsuccessful PIN attempts',`Basket ${b.id} · Review access attempts; no entry was granted.`);$('#pin-error').textContent='That PIN did not match. Try the demo PIN: 1234.';save();return}b.locked=false;state.failedPins=0;event(`Basket ${b.id} unlocked`,'Alex Johnson · Authorized PIN access');save();unlocked(b);render()}});
document.addEventListener('click',e=>{let t=e.target.closest('button');if(!t)return;if(t.dataset.go){close();location.hash=t.dataset.go;return}if(t.dataset.basket){access(t.dataset.basket);return}if(t.dataset.weight){let b=state.baskets.find(b=>b.id===activeBasket);if(!b||b.locked)return;let delta=Number(t.dataset.weight);if(b.weight+delta<0){toast('The basket is already empty.');return}b.weight=Math.round((b.weight+delta)*100)/100;event(`Basket ${b.id} weight updated`,`${delta>0?'Added':'Removed'} 250 g during authorized access · ${b.weight.toFixed(2)} kg`);save();unlocked(b);render();return}if(t.dataset.lock){let b=state.baskets.find(b=>b.id===t.dataset.lock);b.locked=true;event(`Basket ${b.id} secured`,'Alex Johnson · Basket locked after access');save();close();render();toast('Basket locked. Your items are secured.');return}if(t.dataset.cancel){let b=state.bookings.find(b=>b.id===t.dataset.cancel);state.bookings=state.bookings.filter(b=>b.id!==t.dataset.cancel);event('Reservation cancelled',new Date(b.start).toLocaleString());save();render();toast('Reservation cancelled. This slot is free again.');return}if(t.dataset.start){if(state.washer!=='Available'){toast('The machine must be available. Complete the current cycle and collect the clothes first.');return}let b=state.bookings.find(b=>b.id===t.dataset.start);modal(`<h2>Start reserved cycle?</h2><p>Demo time travel: start your reserved slot now for the presentation. It runs for 45 simulated minutes; Admin demo can complete it instantly.</p><button class="btn primary" data-run="${b.id}">Start demo cycle</button>`);return}if(t.dataset.run){state.washer='In Use';state.washEnd=Date.now()+45*60000;state.bookings=state.bookings.filter(b=>b.id!==t.dataset.run);event('Washing cycle started','Alex Johnson · Demo early start');save();close();render();toast('Cycle started. You’ll receive a completion notification.');return}if(t.dataset.resolve){state.alerts.find(a=>a.id===t.dataset.resolve).resolved=true;event('Alert reviewed','Admin demo · Activity marked reviewed');save();render();toast('Alert marked reviewed.');return}switch(t.dataset.action){case'close':close();break;case'book':book();break;case'micro':microModal();break;case'micro-toggle':state.micro=state.micro==='Available'?'In Use':'Available';state.microEnd=state.micro==='In Use'?Date.now()+20000:null;event('Microwave status updated',state.micro+' · Simulated controller');save();render();microModal();break;case'complete':complete();break;case'collect':collect();break;case'unexpected':{let b=state.baskets.find(b=>b.user&&b.locked);if(!b){toast('Lock an occupied basket first.');return}b.weight=Math.max(0,b.weight-.4);alertEvent('Unexpected weight change',`Basket ${b.id}: −400 g reading while locked. Possible sensor drift, misplaced item, or activity requiring review. This is not proof of theft.`);save();render();break}case'reset':modal('<h2>Reset the demonstration?</h2><p>This clears this browser’s demo bookings, alerts, and basket changes, and restores the sample scenario.</p><button class="btn danger" data-action="reset-confirm">Reset demo data</button>');break;case'reset-confirm':state=seed();save();close();render();toast('Demo restored. Ready for your presentation.');break}});
document.addEventListener('change',e=>{if(e.target.dataset.device){let k=e.target.dataset.device;state[k]=e.target.value;if(k==='washer'&&state[k]==='In Use')state.washEnd=Date.now()+18*60000;event('Appliance status changed',`${k==='micro'?'Microwave':k==='washer'?'Washing machine':'Refrigerator'} · ${state[k]} · Admin demo`);save();render();toast('Appliance status updated.')}if(e.target.dataset.assign){let b=state.baskets.find(b=>b.id===e.target.dataset.assign);b.user=e.target.value||null;b.locked=true;b.pin=b.user==='Alex Johnson'?'1234':'2468';if(!b.user)b.weight=0;event(`Basket ${b.id} assignment updated`,b.user||'Basket now available');save();render();toast('Basket assignment updated.')}});$('#notifications').onclick=()=>{modal(`<h2>Notifications</h2><p>In-app demo notifications · No real contact details needed.</p>${state.notifications.length?state.notifications.map(n=>`<div class="notification"><b>${esc(n.title)}</b><p>${esc(n.detail)}</p><small>${ago(n.time)}</small></div>`).join(''):'<div class="empty">You’re all caught up. Wash completion and sensor alerts will appear here.</div>'}`)};document.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='Tab'&&$('.modal')){let els=[...$('.modal').querySelectorAll('button,input,select,a')];let f=els[0],l=els.at(-1);if(e.shiftKey&&document.activeElement===f){e.preventDefault();l.focus()}else if(!e.shiftKey&&document.activeElement===l){e.preventDefault();f.focus()}}});window.addEventListener('hashchange',()=>{page=['overview','appliances','bookings','baskets','activity','admin'].includes(location.hash.slice(1))?location.hash.slice(1):'overview';render();window.scrollTo(0,0)});page=location.hash.slice(1)||'overview';render();setInterval(()=>{if(state.washer==='In Use'&&Date.now()>=state.washEnd)complete();if(state.micro==='In Use'&&state.microEnd&&Date.now()>=state.microEnd){state.micro='Available';state.microEnd=null;event('Microwave is available','Demo heating cycle completed');notify('Microwave is available','Your demo heating cycle is complete.');render()}let w=$('#wash-min');if(w)w.textContent=remaining()},1000);
